using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Collections.Concurrent;
using System.Net;
using System.Net.Sockets;

namespace SecureAuth.Core
{
    public sealed class NtlmAuthenticator : IDisposable
    {
        private readonly ConcurrentDictionary<string, AuthSession> _sessions;
        private readonly CancellationTokenSource _shutdownCts;
        private readonly ManualResetEventSlim _drainComplete;
        private volatile int _state; // 0=running, 1=draining, 2=stopped
        private const int STATE_RUNNING = 0;
        private const int STATE_DRAINING = 1;
        private const int STATE_STOPPED = 2;

        // Bound the number of cached sessions to prevent unbounded memory
        // growth (CWE-770) from unauthenticated callers supplying many
        // distinct usernames.
        private const int MAX_SESSIONS = 10000;
        private int _sessionCount;

        public NtlmAuthenticator()
        {
            _sessions = new ConcurrentDictionary<string, AuthSession>();
            _shutdownCts = new CancellationTokenSource();
            _drainComplete = new ManualResetEventSlim(false);
            _state = STATE_RUNNING;
            _sessionCount = 0;
        }

        public AuthResult Authenticate(string username, byte[] clientResponse, byte[] serverChallenge)
        {
            if (_state != STATE_RUNNING)
                return AuthResult.ServiceUnavailable();

            if (string.IsNullOrEmpty(username))
                return AuthResult.Failed();

            var session = GetOrCreateSession(username);
            if (session == null)
                return AuthResult.ServiceUnavailable();

            return ValidateNtlmResponse(session, clientResponse, serverChallenge);
        }

        private AuthSession GetOrCreateSession(string username)
        {
            // Fast path: existing session.
            if (_sessions.TryGetValue(username, out var existing))
                return existing;

            // Enforce a hard cap on the number of distinct sessions to
            // prevent memory-exhaustion DoS from untrusted usernames.
            var created = new AuthSession(username);
            var actual = _sessions.GetOrAdd(username, created);
            if (ReferenceEquals(actual, created))
            {
                // We inserted a new session; account for it and enforce cap.
                if (Interlocked.Increment(ref _sessionCount) > MAX_SESSIONS)
                {
                    // Roll back: over capacity, remove and reject.
                    if (_sessions.TryRemove(username, out var removed))
                    {
                        Interlocked.Decrement(ref _sessionCount);
                        removed.Dispose();
                    }
                    return null;
                }
            }
            else
            {
                // Another thread created it first; dispose our unused instance.
                created.Dispose();
            }
            return actual;
        }

        private AuthResult ValidateNtlmResponse(AuthSession session, byte[] clientResponse, byte[] serverChallenge)
        {
            byte[] expectedHash = ComputeExpectedResponse(session, serverChallenge);
            bool isValid = CompareHashes(clientResponse, expectedHash);

            if (isValid)
            {
                session.LastAuthenticated = DateTime.UtcNow;
                return AuthResult.Success(session.Username);
            }
            return AuthResult.Failed();
        }

        private byte[] ComputeExpectedResponse(AuthSession session, byte[] serverChallenge)
        {
            // Retrieve stored NT hash for the user
            byte[] ntHash = session.GetStoredNtHash();

            // NTLMv2: HMAC-MD5(NT-Hash, uppercase(username) + domain)
            // Then HMAC-MD5(ntlmv2Hash, serverChallenge + clientChallenge)
            using (var hmac = new HMACMD5(ntHash))
            {
                byte[] userDomain = Encoding.Unicode.GetBytes(
                    session.Username.ToUpperInvariant() + session.Domain);
                byte[] ntlmv2Hash = hmac.ComputeHash(userDomain);

                using (var hmac2 = new HMACMD5(ntlmv2Hash))
                {
                    return hmac2.ComputeHash(serverChallenge);
                }
            }
        }

        /// <summary>
        /// Constant-time comparison to prevent timing attacks.
        /// Uses fixed-time comparison regardless of system state.
        /// </summary>
        private bool CompareHashes(byte[] provided, byte[] expected)
        {
            if (provided == null || expected == null)
                return false;
            if (provided.Length != expected.Length)
                return false;

            return CryptographicOperations.FixedTimeEquals(provided, expected);
        }

        public void InitiateGracefulShutdown(TimeSpan drainTimeout)
        {
            if (Interlocked.CompareExchange(ref _state, STATE_DRAINING, STATE_RUNNING) == STATE_RUNNING)
            {
                // Reject new requests immediately via state check in Authenticate
                // Wait for in-flight to complete naturally
                Thread.Sleep(drainTimeout);
                Interlocked.Exchange(ref _state, STATE_STOPPED);
                _drainComplete.Set();
                _shutdownCts.Cancel();
            }
        }

        public void Dispose()
        {
            InitiateGracefulShutdown(TimeSpan.FromSeconds(5));
            _drainComplete.Wait(TimeSpan.FromSeconds(10));
            _shutdownCts.Dispose();
            _drainComplete.Dispose();

            foreach (var session in _sessions.Values)
                session.Dispose();
            _sessions.Clear();
        }
    }

    public class AuthSession : IDisposable
    {
        public string Username { get; }
        public string Domain { get; set; } = "WORKGROUP";
        public DateTime LastAuthenticated { get; set; }
        private byte[] _storedNtHash;

        public AuthSession(string username)
        {
            Username = username;
            _storedNtHash = LoadNtHashFromStore(username);
        }

        public byte[] GetStoredNtHash()
        {
            return (byte[])_storedNtHash.Clone();
        }

        private byte[] LoadNtHashFromStore(string username)
        {
            // In production, loads from secure credential store
            // Returns the NT hash (MD4 of Unicode password)
            return new byte[16]; // placeholder
        }

        public void Dispose()
        {
            if (_storedNtHash != null)
                CryptographicOperations.ZeroMemory(_storedNtHash);
        }
    }

    public class AuthResult
    {
        public bool IsSuccess { get; private set; }
        public string Username { get; private set; }
        public bool IsUnavailable { get; private set; }

        public static AuthResult Success(string user) => new AuthResult { IsSuccess = true, Username = user };
        public static AuthResult Failed() => new AuthResult { IsSuccess = false };
        public static AuthResult ServiceUnavailable() => new AuthResult { IsUnavailable = true };
    }
}
